    23→
    24→pub type ColumnIndex = u64;
    25→pub type Cell<E> = FixedVector<u8, <E as EthSpec>::BytesPerCell>;
    26→pub type DataColumn<E> = VariableList<Cell<E>, <E as EthSpec>::MaxBlobCommitmentsPerBlock>;
    27→
    28→/// Identifies a set of data columns associated with a specific beacon block.
    29→#[derive(Encode, Decode, Clone, Debug, PartialEq, TreeHash, Deserialize)]
    30→#[context_deserialize(ForkName)]
    31→pub struct DataColumnsByRootIdentifier<E: EthSpec> {
    32→    pub block_root: Hash256,
    33→    pub columns: VariableList<ColumnIndex, E::NumberOfColumns>,
    34→}
    35→
    36→pub type DataColumnSidecarList<E> = Vec<Arc<DataColumnSidecar<E>>>;
    37→
    38→#[cfg_attr(
    39→    feature = "arbitrary",
    40→    derive(arbitrary::Arbitrary),
    41→    arbitrary(bound = "E: EthSpec")
    42→)]
    43→#[derive(
    44→    Debug, Clone, Serialize, Deserialize, Encode, Decode, TreeHash, TestRandom, Derivative,
    45→)]
    46→#[serde(bound = "E: EthSpec")]
    47→#[derivative(PartialEq, Eq, Hash(bound = "E: EthSpec"))]
    48→#[context_deserialize(ForkName)]
    49→pub struct DataColumnSidecar<E: EthSpec> {
    50→    #[serde(with = "serde_utils::quoted_u64")]
    51→    pub index: ColumnIndex,
    52→    #[serde(with = "ssz_types::serde_utils::list_of_hex_fixed_vec")]
    53→    pub column: DataColumn<E>,
    54→    /// All the KZG commitments and proofs associated with the block, used for verifying sample cells.
    55→    pub kzg_commitments: KzgCommitments<E>,
    56→    pub kzg_proofs: VariableList<KzgProof, E::MaxBlobCommitmentsPerBlock>,
    57→    pub signed_block_header: SignedBeaconBlockHeader,
    58→    /// An inclusion proof, proving the inclusion of `blob_kzg_commitments` in `BeaconBlockBody`.
    59→    pub kzg_commitments_inclusion_proof: FixedVector<Hash256, E::KzgCommitmentsInclusionProofDepth>,
    60→}
    61→
    62→impl<E: EthSpec> DataColumnSidecar<E> {
    63→    pub fn slot(&self) -> Slot {
    64→        self.signed_block_header.message.slot
    65→    }
    66→
    67→    pub fn epoch(&self) -> Epoch {
    68→        self.slot().epoch(E::slots_per_epoch())
    69→    }
    70→
    71→    pub fn block_root(&self) -> Hash256 {
    72→        self.signed_block_header.message.tree_hash_root()
    73→    }
    74→
    75→    pub fn block_parent_root(&self) -> Hash256 {
    76→        self.signed_block_header.message.parent_root
    77→    }
    78→
    79→    pub fn block_proposer_index(&self) -> u64 {
    80→        self.signed_block_header.message.proposer_index
    81→    }
    82→
    83→    /// Verifies the kzg commitment inclusion merkle proof.
    84→    pub fn verify_inclusion_proof(&self) -> bool {
    85→        let blob_kzg_commitments_root = self.kzg_commitments.tree_hash_root();
    86→
    87→        verify_merkle_proof(
    88→            blob_kzg_commitments_root,
    89→            &self.kzg_commitments_inclusion_proof,
    90→            E::kzg_commitments_inclusion_proof_depth(),
    91→            BLOB_KZG_COMMITMENTS_INDEX,
    92→            self.signed_block_header.message.body_root,
    93→        )
    94→    }
    95→
    96→    pub fn min_size() -> usize {
    97→        // min size is one cell
    98→        Self {
    99→            index: 0,
